// === Tab: mySketch.js ===
class Particle {

    constructor(pos, targ){
        this.pos = pos;
        this.targ = targ
        this.vel = createVector(0,0);
        this.acc = createVector(0,0);
    }

    getTargForce(){
        let diff = p5.Vector.sub(this.targ, this.pos);
        let len = diff.mag();
        let force = createVector(0,0);

        if (len > 0.5){
            diff.normalize();
            let multiplier = map(min(len, 5), 0, 5, 0, 0.5);
            diff.mult(multiplier);
            force.add(diff);
        }
        return force;
    }

    getRepelForce(){
        let m = createVector(
            (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + bounds.w/2, 
            (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - bounds.h/2
        );
        var diff = p5.Vector.sub(this.pos, m);
        var len = diff.mag();
        var force = createVector(0,0);
        if (len < 30){
            force.add(diff);
            force.mult(0.3);
        }
        return force;
    }

    update(){
        let tForce = this.getTargForce();
        let rForce = this.getRepelForce();
        var force = p5.Vector.add(tForce, rForce);

        this.vel.mult(0.98);
        this.vel.add(force);
        this.pos.add(this.vel);
    }

    render(){
        stroke(251, 129, 24);
        circle(this.pos.x, this.pos.y, 5);
    }
}

function preload(){
    font = loadFont("https://openprocessing.org/sketch/1907298/files/FantasqueSansMono-Regular.ttf");
}

let bounds;
let particles = [];  
let inp;
let txt;
let button;

function restart(){
    txt = inp.value();
    let fontSize = min(width/2, height/2)*0.6;
    bounds = font.textBounds(txt, width/2, height/2, fontSize);
    let points = font.textToPoints(txt, width/2, height/2, fontSize);
    particles = [];
    for (let i = 0; i < points.length; i++){
        let p = points[i];
        let pos = createVector(p.x,p.y);
        let targ = createVector(p.x,p.y);
        let part = new Particle(pos, targ);
        particles.push(part);
    }
}

function setup(){
    createCanvas(windowWidth,windowHeight);

    inp = createInput("art.rchu.cc");
    inp.position(20,65);
    inp.input(restart);
    inp.style("background", "rgb(0,0,0)");
    inp.style("color", "rgb(255,255,255)");
    inp.style("border", "1px solid rgb(255, 255,255)");
    inp.style("padding", "5px");
    inp.style("border-radius", "3px");

    restart();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  restart();
}

function draw(){
    translate(-bounds.w/2, bounds.h/2);
    background(0, 0, 0, 100);
    noFill();

    for (let p of particles){
        p.update();
        p.render();
    }
}

